import{_ as a,o as t,c as i,a5 as n}from"./chunks/framework.bIR-4glx.js";const c=JSON.parse('{"title":"作品简报与交付卡","description":"用受众、基线、版本、反馈、质量门和回滚条件管理一个可复查、可交接的学习或项目作品。","frontmatter":{"title":"作品简报与交付卡","description":"用受众、基线、版本、反馈、质量门和回滚条件管理一个可复查、可交接的学习或项目作品。","updated":"2026-08-31T00:00:00.000Z","worksheetDownload":{"url":"/downloads/worksheets/artifact-brief.zh.md","name":"artifact-brief.zh.md"}},"headers":[],"relativePath":"templates/artifact-brief.md","filePath":"templates/artifact-brief.md","lastUpdated":1788134400000}'),e={name:"templates/artifact-brief.md"};function l(p,s,d,h,r,E){return t(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="作品简报与交付卡" tabindex="-1">作品简报与交付卡 <a class="header-anchor" href="#作品简报与交付卡" aria-label="Permalink to &quot;作品简报与交付卡&quot;">​</a></h1><p>作品不必从一开始就完整，但必须从一开始就有边界。复制这张卡到私有项目目录，保留独立版、修订版、反馈版和交付版。不要写入密码、客户资料、未获授权的第三方信息或不必要的隐私。</p><h2 id="_1-作品边界" tabindex="-1">1. 作品边界 <a class="header-anchor" href="#_1-作品边界" aria-label="Permalink to &quot;1. 作品边界&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Artifact Brief — YYYY-MM-DD</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">作品名称：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">真实场景：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">受众/使用者：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">要解决的一个问题：</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">输入材料与来源：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">我当前的基线：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">关键假设：</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">最小交付物：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">格式、时间与其他限制：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">完成标准：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">明确不做什么：</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">第一版截止时间：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">谁会提供反馈：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">需要保留的证据：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">失败时如何缩小、暂停或回滚：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">下一次复查日期：</span></span></code></pre></div><h2 id="_2-四个版本" tabindex="-1">2. 四个版本 <a class="header-anchor" href="#_2-四个版本" aria-label="Permalink to &quot;2. 四个版本&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>完成条件</th><th>保留什么</th></tr></thead><tbody><tr><td>独立版</td><td>不看答案、不让 AI 代写，完成最小动作</td><td>原始文件、用时、卡点</td></tr><tr><td>结构版</td><td>受众能找到问题、结论和下一步</td><td>结构差异、事实与推测标记</td></tr><tr><td>反馈版</td><td>真实读者、用户、同伴或明确角色的 AI 完成审阅</td><td>反馈、错误分类、采纳/拒绝理由</td></tr><tr><td>交付版</td><td>他人不依赖你的口头补充也能开始使用</td><td>版本、限制、来源、已知问题、交接记录</td></tr></tbody></table><h2 id="_3-质量门" tabindex="-1">3. 质量门 <a class="header-anchor" href="#_3-质量门" aria-label="Permalink to &quot;3. 质量门&quot;">​</a></h2><table tabindex="0"><thead><tr><th>门</th><th>检查问题</th><th>证据位置</th><th>负责人/日期</th></tr></thead><tbody><tr><td>清楚</td><td>受众知道问题和下一步吗？</td><td></td><td></td></tr><tr><td>准确</td><td>事实、引用、代码和数字能回到来源或测试吗？</td><td></td><td></td></tr><tr><td>可用</td><td>主要动作在真实限制下能完成吗？</td><td></td><td></td></tr><tr><td>可维护</td><td>版本、依赖、限制和接手人清楚吗？</td><td></td><td></td></tr><tr><td>可负责</td><td>隐私、版权、权限和错误后果已处理吗？</td><td></td><td></td></tr></tbody></table><p>没有证据的“通过”先写成“待核验”。速度、字数和功能数量只是代理指标，不能替代质量门。</p><h2 id="_4-ai-与反馈记录" tabindex="-1">4. AI 与反馈记录 <a class="header-anchor" href="#_4-ai-与反馈记录" aria-label="Permalink to &quot;4. AI 与反馈记录&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AI/工具与日期：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">允许它做的工作：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">我保留的人类判断：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">它指出的三个最高影响问题：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">我采纳/拒绝了什么，为什么：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">真实读者/用户复述的主旨：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">最需要修正的一处：</span></span></code></pre></div><p>先保存自己的版本，再让 AI 诊断、模拟受众或生成平行任务。关键事实、权限、隐私、成本和最终署名由人确认。</p><h2 id="_5-交付与回滚" tabindex="-1">5. 交付与回滚 <a class="header-anchor" href="#_5-交付与回滚" aria-label="Permalink to &quot;5. 交付与回滚&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">交付对象与授权范围：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">交付日期与版本：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">使用说明：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">已知限制：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">支持与联系人：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">成本与留存期限：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">暂停/降级/回滚触发条件：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">发现问题后的通知对象：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">下一次复查日期：</span></span></code></pre></div><p>交付不是终点。至少在 3–7 天后用相近条件复测一次，记录别人是否能独立开始、哪里需要解释，以及下一版本只改变什么。</p><p>相关章节：<a href="./../threads/part-3/4-artifacts-and-delivery">作品篇：把学会变成做出</a> ｜ <a href="./90-day-cycle">九十日行动总表</a></p>`,16)])])}const o=a(e,[["render",l]]);export{c as __pageData,o as default};
